insert into public.vm_daily_topics (day, theme, title, prompt, sort_order) values
  ('2026-09-10', 'Fundraising', 'Take the money?', 'An investor offers a term sheet today at a valuation 30% below what you wanted. Do you close fast or keep raising? What would change your answer?', 1),
  ('2026-09-11', 'Bootstrapping', 'The first $10k', 'You have $10,000 and 90 days. What is the single experiment you would run to prove people will pay?', 2),
  ('2026-09-12', 'Customers', 'Who is not your customer?', 'Name the customer you are deliberately saying no to right now. Why does saying no make the business stronger?', 3),
  ('2026-09-13', 'Pricing', 'Double it', 'If you doubled your price tomorrow, who would leave and who would stay? What does that tell you about who you actually serve?', 4),
  ('2026-09-14', 'Team', 'The first hire', 'Your first hire sets the culture more than any document. What role would you hire first, and what one trait is non-negotiable?', 5),
  ('2026-09-15', 'Product', 'Cut a feature', 'Which feature would you remove from your product this week to make it better? What is stopping you?', 6),
