  ('2026-09-17', 'Finance', 'Runway math', 'How many months of runway do you have, and what would you cut first if it were half that?', 8),
  ('2026-09-18', 'Negotiation', 'Walk-away point', 'In your last negotiation, did you know your walk-away point before you sat down? How did that change the outcome?', 9),
  ('2026-09-19', 'Mindset', 'Losing well', 'Describe a game or deal you lost that taught you more than a win would have.', 10),
  ('2026-09-20', 'Risk', 'All-in or hedge?', 'When is going all-in on one bet the right call for a founder, and when is it just gambling with other people''s time?', 11),
  ('2026-09-21', 'Exit', 'What does done look like?', 'If someone offered to buy your company today, what number, and what would you do the day after?', 12),
  ('2026-09-22', 'Fundraising', 'Friends and family', 'Would you take money from family? What rules would you set so a bad quarter does not ruin a good relationship?', 13),
  ('2026-09-23', 'Bootstrapping', 'Revenue before product', 'Have you ever sold something before it existed? What did the buyer actually pay for?', 14),
  ('2026-09-24', 'Customers', 'The complaint that mattered', 'What is the most useful complaint you ever received, and what did you change because of it?', 15),
  ('2026-09-25', 'Pricing', 'Free vs. cheap', 'Is a free tier a marketing cost or a product decision? Where should the free line sit for a business like yours?', 16),
  ('2026-09-26', 'Team', 'Co-founder chemistry', 'What is the one conversation every co-founder pair should have before incorporating?', 17),
  ('2026-09-27', 'Product', 'The 10x question', 'What would your product have to do to be ten times better rather than ten percent better?', 18),
  ('2026-09-28', 'Growth', 'Referrals', 'Why do your customers refer you today, if they do? What would make them do it twice as often?', 19),
  ('2026-09-29', 'Finance', 'Cash vs. profit', 'Explain, in one sentence you could say to a new founder, why a profitable company can still run out of cash.', 20),
  ('2026-09-30', 'Negotiation', 'The first offer', 'Should you make the first offer or wait for theirs? Does your answer change when you are the smaller party?', 21),
  ('2026-10-01', 'Mindset', 'Your default move', 'In games, most of us have a default move under pressure. What is yours, and does it serve you in business?', 22),
  ('2026-10-02', 'Risk', 'Reversible decisions', 'Which decision this month is reversible and which is not? Are you spending your deliberation on the right one?', 23),
  ('2026-10-03', 'Exit', 'Build to sell or build to keep?', 'Does knowing whether you want to sell change how you build? What would you do differently either way?', 24),
  ('2026-10-04', 'Fundraising', 'The one-line pitch', 'Write your company in one sentence a stranger could repeat correctly an hour later.', 25),
  ('2026-10-05', 'Bootstrapping', 'Doing it by hand', 'What part of your business could you run manually for another six months instead of building software for it?', 26),
  ('2026-10-06', 'Customers', 'Segment of one', 'Describe your very best customer as a person: their job, their day, the moment they thought of you.', 27),
  ('2026-10-07', 'Pricing', 'Anchors', 'What does your pricing page anchor against? Would a different anchor make your real price feel like a bargain?', 28),
  ('2026-10-08', 'Team', 'Letting someone go', 'What signal tells you it is time to part ways with a teammate, and how long do founders usually wait past it?', 29),
  ('2026-10-09', 'Product', 'Shipping cadence', 'Weekly releases or big launches? Which fits your customers, and which fits your team?', 30),
  ('2026-10-10', 'Growth', 'Retention first', 'If retention is weak, is spending on acquisition pouring water into a leaky bucket, or is it how you find the leak?', 31),
  ('2026-10-11', 'Finance', 'Unit economics', 'What does it cost you to acquire a customer, and what do they pay you over their lifetime? If you do not know, how will you find out this week?', 32),
  ('2026-10-12', 'Negotiation', 'Trading, not conceding', 'What is one thing you could ask for in return the next time someone asks you for a discount?', 33),
  ('2026-10-13', 'Mindset', 'Founder energy', 'What activity reliably refills your energy, and when did you last schedule it?', 34),
  ('2026-10-14', 'Risk', 'The second bet', 'If your first product fails, what is the second bet you already know you would make?', 35),
  ('2026-10-15', 'Exit', 'Acqui-hire', 'Would you accept an acquisition that keeps the team but kills the product? What would make it worth it?', 36),
  ('2026-10-16', 'Fundraising', 'Angels vs. funds', 'For a company at your stage, is an angel round or an institutional fund the better first check, and why?', 37),
  ('2026-10-17', 'Bootstrapping', 'Side project rules', 'If you are building alongside a job, what rule protects the job, and what rule protects the project?', 38),
  ('2026-10-18', 'Customers', 'Churn interview', 'What question would you ask a customer who just cancelled that they would actually answer honestly?', 39),
  ('2026-10-19', 'Pricing', 'Annual plans', 'Should you offer an annual discount? What does the cash-up-front buy you, and what does it cost you in flexibility?', 40),
  ('2026-10-20', 'Team', 'Equity split', 'Equal splits or contribution-based? What information would you need to split fairly on day one?', 41),
  ('2026-10-21', 'Product', 'Onboarding', 'What is the first thing a new user should accomplish in five minutes, and does your product make that obvious?', 42),
  ('2026-10-22', 'Growth', 'Partnerships', 'Name a company that already has your customers. What could you offer them that costs you little?', 43),
  ('2026-10-23', 'Finance', 'Price of speed', 'When is paying more to move faster the right trade, and when is it a founder avoiding a hard conversation?', 44),
  ('2026-10-24', 'Negotiation', 'Silence', 'Have you ever won a negotiation by saying nothing? What happened in the pause?', 45),
  ('2026-10-25', 'Mindset', 'Comparison', 'Whose progress do you compare yourself to, and is that comparison making you better or just anxious?', 46),
  ('2026-10-26', 'Risk', 'Insurance you skipped', 'What risk are you currently uninsured against, financially or operationally, and is that a choice or an oversight?', 47),
  ('2026-10-27', 'Exit', 'Founder role after', 'After an exit, most founders stay one to three years. What would make you want to stay longer than you had to?', 48),
  ('2026-10-28', 'Fundraising', 'Dilution', 'How much of your company would you give up to double your odds of success? Where is your line?', 49),
  ('2026-10-29', 'Bootstrapping', 'Charging early', 'What is the earliest moment you could have charged for your product? What held you back?', 50),
  ('2026-10-30', 'Customers', 'Community', 'Do your customers talk to each other? If they did, what would they say about you?', 51),
  ('2026-10-31', 'Pricing', 'Discounts', 'What is your rule for discounts, and did the last one you gave follow it?', 52),
  ('2026-11-01', 'Team', 'Remote or together', 'Would you build your first team in one room or across time zones? What does the product need from the team?', 53),
  ('2026-11-02', 'Product', 'Roadmap honesty', 'What is on your roadmap that you privately doubt you will ship? Why is it still there?', 54),
  ('2026-11-03', 'Growth', 'Content', 'What could you write, record, or teach every week that your customers would actually seek out?', 55),
  ('2026-11-04', 'Finance', 'Budget versus forecast', 'Do you run on a budget, a forecast, or gut feel? What would the next level of rigor cost you in time?', 56),
  ('2026-11-05', 'Negotiation', 'Multiple issues', 'The best deals trade across several issues, not just price. What are the three issues in your next deal?', 57),
  ('2026-11-06', 'Mindset', 'Learning loop', 'How do you capture what you learned this week so it changes what you do next week?', 58),
  ('2026-11-07', 'Risk', 'Key person', 'If you were unavailable for a month, what breaks first? What could you fix about that this quarter?', 59),
  ('2026-11-08', 'Exit', 'Secondary sales', 'Should founders take money off the table in a big round? What does it do to their risk appetite?', 60),
  ('2026-11-09', 'Fundraising', 'Updates', 'Do you send investor updates? What would you include if you knew a future investor was reading them?', 61),
  ('2026-11-10', 'Bootstrapping', 'Services to product', 'Could you fund the product by selling the service version first? What would the clients teach you?', 62),
  ('2026-11-11', 'Customers', 'Support as research', 'What did your last support ticket reveal that your analytics never could?', 63),
  ('2026-11-12', 'Pricing', 'Value metric', 'What unit should you charge by: seats, usage, outcomes? Which one grows as your customer succeeds?', 64),
  ('2026-11-13', 'Team', 'Advisors', 'What would make an advisor worth a slice of equity, and what would you expect from them monthly?', 65),
  ('2026-11-14', 'Product', 'Competitor feature', 'A competitor shipped something your customers asked for. Copy it, ignore it, or leapfrog? How do you decide?', 66),
  ('2026-11-15', 'Growth', 'Events', 'Would you host a small event for your customers? What would they get that a newsletter cannot give them?', 67),
  ('2026-11-16', 'Finance', 'Debt', 'When is borrowing better than selling equity for a company like yours?', 68),
  ('2026-11-17', 'Negotiation', 'Deadlines', 'Real deadlines create decisions; fake ones create distrust. How can you tell which kind you are facing?', 69),
  ('2026-11-18', 'Mindset', 'Saying no', 'What opportunity did you say no to recently, and how did it feel a month later?', 70),
  ('2026-11-19', 'Risk', 'Regulation', 'Is there a rule or law that could change your business overnight? How would you know it was coming?', 71),
  ('2026-11-20', 'Exit', 'The buyer''s view', 'If you were the acquirer, what about your company would worry you most in diligence?', 72),
  ('2026-11-21', 'Fundraising', 'No', 'What is the most useful investor "no" you have received, and what did you do with it?', 73),
  ('2026-11-22', 'Bootstrapping', 'Tools you overpay for', 'Which subscription could you cancel today without anyone noticing for a month?', 74),
  ('2026-11-23', 'Customers', 'Onboarding call', 'Should every new customer get a human call? At what scale does that stop being the answer?', 75),
  ('2026-11-24', 'Pricing', 'Enterprise tier', 'What would a customer paying ten times your top price expect, and could you deliver it?', 76),
  ('2026-11-25', 'Team', 'Interviewing', 'What is the one question in your interviews that actually predicts performance?', 77),
  ('2026-11-26', 'Product', 'Data you ignore', 'What metric do you collect but never look at? Should you stop collecting it or start acting on it?', 78),
  ('2026-11-27', 'Growth', 'Pricing as growth', 'Could a lower entry price grow you faster than more marketing? What is the risk?', 79),
  ('2026-11-28', 'Finance', 'Founder salary', 'What should a founder pay themselves before the company is profitable, and why does the answer matter to investors?', 80),
  ('2026-11-29', 'Negotiation', 'Relationship vs. deal', 'When is it right to leave money on the table to protect a relationship?', 81),
  ('2026-11-30', 'Mindset', 'Playing styles', 'Are you a builder, a dealmaker, or a wildcard at the table? Is that who you are at work?', 82),
  ('2026-12-01', 'Risk', 'Concentration', 'What share of revenue comes from your biggest customer? At what percentage does that become a problem?', 83),
  ('2026-12-02', 'Exit', 'Legacy', 'Beyond the money, what would you want a buyer to keep exactly as it is?', 84),
  ('2026-12-03', 'Fundraising', 'Pitch feedback', 'What part of your pitch gets the most questions? Is it unclear, or is it the interesting part?', 85),
  ('2026-12-04', 'Bootstrapping', 'Profit first', 'Would you rather grow 20% profitably or 100% at a loss this year? Who is your answer for?', 86),
  ('2026-12-05', 'Customers', 'Lost deal', 'Think of a deal you lost to a competitor. What did they understand about the customer that you did not?', 87),
  ('2026-12-06', 'Pricing', 'Raising prices', 'How would you tell existing customers about a price increase so that most of them stay?', 88),
  ('2026-12-07', 'Team', 'Rituals', 'What weekly ritual keeps your team honest about progress? If none, what would you start on Monday?', 89),
  ('2026-12-08', 'Product', 'Your best day', 'Describe the best day a customer can have with your product. How often does it actually happen?', 90)
insert into public.vm_quiz_questions (day, theme, question, options, answer_index, explanation, sort_order) values
  ('2026-09-10', 'Finance', 'A company sells $50k of product on 60-day terms and pays $40k of costs immediately. This month its cash position...', '["Rises by $10k","Falls by $40k","Rises by $50k","Is unchanged"]'::jsonb, 1, 'Revenue was earned but the cash arrives in 60 days; the $40k of costs left the account now. Profit on paper, cash out the door.', 1),
  ('2026-09-11', 'Fundraising', 'A SAFE (Simple Agreement for Future Equity) converts into shares...', '["Immediately at signing","At the next priced round","Only if the company is acquired","After 12 months"]'::jsonb, 1, 'A SAFE gives the investor the right to shares at the next priced financing, usually at a discount or under a valuation cap.', 2),
  ('2026-09-12', 'Pricing', 'Charging by "seats" is an example of a...', '["Cost-plus model","Value metric","Loss leader","Freemium tier"]'::jsonb, 1, 'The value metric is the unit you charge for. Seats scale with team size; usage or outcomes are alternatives.', 3),
  ('2026-09-13', 'Customers', 'Net Revenue Retention above 100% means...', '["You lost no customers","Existing customers pay you more over time than you lose to churn","You have no discounts","Your CAC is zero"]'::jsonb, 1, 'NRR counts expansion minus churn across the existing base. Over 100%, the base grows even with zero new customers.', 4),
  ('2026-09-14', 'Negotiation', 'BATNA stands for...', '["Best Alternative To a Negotiated Agreement","Basic Agreement Terms and Negotiation Aims","Bargaining And Terms Negotiation Approach","Buyer Accepted Terms, No Amendments"]'::jsonb, 0, 'Your BATNA is what you do if the deal fails. Knowing it is what makes a walk-away credible.', 5),
  ('2026-09-15', 'Finance', 'Gross margin is...', '["Revenue minus all expenses","Revenue minus the direct cost of delivering the product","Profit after tax","Cash in the bank"]'::jsonb, 1, 'Gross margin strips out cost of goods sold only; operating costs come later.', 6),
  ('2026-09-16', 'Growth', 'CAC payback period measures...', '["How long until a customer refers someone","Months of gross profit needed to recover the cost of acquiring a customer","Time to first purchase","Length of a sales cycle"]'::jsonb, 1, 'Divide CAC by monthly gross profit per customer. Shorter payback means growth needs less cash.', 7),
  ('2026-09-17', 'Fundraising', 'A "pre-money valuation" of $8M with a $2M raise gives investors...', '["25% of the company","20% of the company","8% of the company","2% of the company"]'::jsonb, 1, 'Post-money is $10M; $2M / $10M = 20%.', 8),
  ('2026-09-18', 'Team', 'Vesting with a one-year cliff means...', '["Shares vest monthly from day one","No shares vest until the first anniversary, then vesting begins","All shares vest after one year","Shares vest only on an exit"]'::jsonb, 1, 'The cliff protects the company if a co-founder leaves early; after it, vesting usually continues monthly.', 9),
  ('2026-09-19', 'Product', 'A "minimum viable product" is best described as...', '["The cheapest thing you can ship","The smallest thing that tests your riskiest assumption with real users","A prototype for investors","Version 1.0"]'::jsonb, 1, 'The point of an MVP is learning, not shipping less; it should answer the question you are least sure about.', 10),
  ('2026-09-20', 'Finance', 'Burn rate is...', '["Monthly revenue","Net cash lost per month","Cost of goods sold","Interest on debt"]'::jsonb, 1, 'Runway = cash / net burn. Cut burn or raise cash to extend it.', 11),
  ('2026-09-21', 'Risk', 'Diversifying across several assets mainly reduces...', '["Expected return","Unsystematic (asset-specific) risk","Taxes","Market risk"]'::jsonb, 1, 'Spreading bets reduces the impact of any one failing; it does not remove market-wide swings.', 12),
  ('2026-09-22', 'Customers', 'Churn of 5% per month compounds to roughly what annual loss?', '["5%","25%","46%","60%"]'::jsonb, 2, '0.95^12 ≈ 0.54, so about 46% of the starting base is gone after a year.', 13),
  ('2026-09-23', 'Pricing', 'Price anchoring works by...', '["Lowering the price over time","Showing a higher reference price first so the real price feels reasonable","Hiding the price until checkout","Matching a competitor"]'::jsonb, 1, 'The first number people see shapes how they judge the next one.', 14),
  ('2026-09-24', 'Negotiation', 'Making the first offer tends to...', '["Always lose","Anchor the negotiation in your favor when you are well informed","Signal weakness","End the negotiation"]'::jsonb, 1, 'Research favors anchoring first when you know the range; wait if you lack information.', 15),
  ('2026-09-25', 'Fundraising', 'Liquidation preference of 1x non-participating means investors get...', '["Their money back first, or their share of proceeds, whichever is greater","Double their money","Nothing until founders are paid","Their money back plus their share"]'::jsonb, 0, 'Non-participating investors choose between the preference and converting to common; participating would take both.', 16),
  ('2026-09-26', 'Growth', 'A viral coefficient above 1 means...', '["Every user costs more than they bring","Each user brings in more than one new user on average","Growth has stopped","Churn is zero"]'::jsonb, 1, 'K > 1 produces self-sustaining growth; most products live well below it.', 17),
  ('2026-09-27', 'Finance', 'Accounts receivable is...', '["Money you owe suppliers","Money customers owe you","Cash in the bank","Inventory"]'::jsonb, 1, 'Receivables are revenue you have earned but not yet collected.', 18),
  ('2026-09-28', 'Team', 'The main purpose of a founders'' agreement is to...', '["Impress investors","Decide roles, equity, vesting, and what happens if someone leaves — before it matters","Register the company","Set salaries"]'::jsonb, 1, 'It is cheap to write and expensive to lack.', 19),
  ('2026-09-29', 'Product', 'Product-market fit is most often described as...', '["A big launch","Customers pulling the product out of your hands: strong retention and organic demand","Positive press","Profitability"]'::jsonb, 1, 'The classic test: would 40%+ of users be very disappointed if the product disappeared?', 20),
  ('2026-09-30', 'Risk', 'Expected value of a bet is...', '["The most likely outcome","Probability-weighted average of all outcomes","The best case","The worst case"]'::jsonb, 1, 'A 10% chance of $1,000 has an EV of $100 even though you usually get nothing.', 21),
  ('2026-10-01', 'Finance', 'EBITDA excludes...', '["Salaries","Interest, taxes, depreciation, and amortization","Marketing","Rent"]'::jsonb, 1, 'It approximates operating cash generation before financing and accounting choices.', 22),
  ('2026-10-02', 'Customers', 'A "jobs to be done" interview asks customers about...', '["Which features they want","The progress they were trying to make when they hired your product","Your competitors","Their budget"]'::jsonb, 1, 'People hire products to get a job done; understanding the job beats collecting feature requests.', 23),
  ('2026-10-03', 'Pricing', 'Freemium works best when...', '["Marginal cost per free user is near zero and free users drive paid conversion or referrals","The product is expensive to serve","You have no competitors","Sales cycles are long"]'::jsonb, 0, 'If free users cost real money to serve and never convert, free is a subsidy, not marketing.', 24),
  ('2026-10-04', 'Negotiation', 'Logrolling in negotiation means...', '["Delaying to gain leverage","Trading concessions on issues each side values differently","Refusing to move","Splitting the difference"]'::jsonb, 1, 'Give on what matters less to you, take on what matters more.', 25),
  ('2026-10-05', 'Fundraising', 'A valuation cap in a convertible note...', '["Limits the founder''s salary","Sets the maximum valuation at which the note converts","Caps how much can be raised","Fixes the interest rate"]'::jsonb, 1, 'It protects early investors from being diluted away by a high-priced next round.', 26),
  ('2026-10-06', 'Growth', 'North star metric should be...', '["Revenue only","The one number that best captures value delivered to customers","Website visits","Headcount"]'::jsonb, 1, 'It should move when customers get value, so the whole team pulls in one direction.', 27),
  ('2026-10-07', 'Finance', 'Working capital is...', '["Founder''s equity","Current assets minus current liabilities","Total assets","Cash burn"]'::jsonb, 1, 'Positive working capital means you can cover near-term obligations.', 28),
  ('2026-10-08', 'Team', 'The Dunning-Kruger effect describes...', '["Experts underestimating others","Low-skill people overestimating their competence","Teams growing too fast","Burnout"]'::jsonb, 1, 'Useful to remember when a founder is very confident in a field they just entered.', 29),
  ('2026-10-09', 'Product', 'A/B testing requires...', '["A big budget","Enough traffic to detect a meaningful difference","A designer","A mobile app"]'::jsonb, 1, 'Small samples produce noise; know your minimum detectable effect before testing.', 30),
  ('2026-10-10', 'Risk', 'Sunk cost fallacy is...', '["Investing based on future value","Continuing because of what you already spent, not what you expect to gain","Cutting losses early","Diversifying"]'::jsonb, 1, 'Money already spent should not influence the next decision.', 31),
  ('2026-10-11', 'Finance', 'Depreciation is...', '["A cash expense","Spreading the cost of an asset over its useful life","A tax refund","Interest"]'::jsonb, 1, 'It reduces profit without touching cash that month.', 32),
  ('2026-10-12', 'Customers', 'Net Promoter Score subtracts...', '["Churned from retained","Detractors (0-6) from promoters (9-10)","Costs from revenue","Free from paid users"]'::jsonb, 1, 'Passives (7-8) count in the total but not in the score.', 33),
  ('2026-10-13', 'Pricing', 'Price discrimination (charging segments differently) is common in...', '["Only illegal businesses","Student pricing, regional pricing, and tiered plans","Nowhere","Only physical goods"]'::jsonb, 1, 'It captures more value when customers differ in willingness to pay.', 34),
  ('2026-10-14', 'Negotiation', 'A "nibble" tactic is...', '["A small extra ask after the main deal is agreed","A big opening demand","Walking away","Silence"]'::jsonb, 0, 'Counter by tying any extra to a concession of your own.', 35),
  ('2026-10-15', 'Fundraising', 'Pro-rata rights let an investor...', '["Veto a sale","Invest in future rounds to keep their ownership percentage","Appoint the CEO","Get paid first"]'::jsonb, 1, 'Popular with early investors who want to double down on winners.', 36),
  ('2026-10-16', 'Growth', 'The "leaky bucket" metaphor refers to...', '["Bad marketing copy","Spending on acquisition while churn drains customers out","Running out of cash","Server outages"]'::jsonb, 1, 'Fix retention before pouring in more acquisition spend.', 37),
  ('2026-10-17', 'Finance', 'A cap table shows...', '["Company expenses","Who owns what percentage of the company","Sales pipeline","Customer list"]'::jsonb, 1, 'Keep it clean; messy cap tables scare investors.', 38),
  ('2026-10-18', 'Team', 'A RACI chart assigns who is...', '["Rich, Able, Creative, Involved","Responsible, Accountable, Consulted, Informed","Ready, Active, Capable, Idle","Recruited, Assigned, Coached, Interviewed"]'::jsonb, 1, 'One accountable owner per decision prevents diffusion of responsibility.', 39),
  ('2026-10-19', 'Product', 'Technical debt is...', '["Money owed to developers","Future work created by shortcuts taken now","Server costs","Bugs"]'::jsonb, 1, 'Some debt is smart; unmanaged debt slows every future release.', 40),
  ('2026-10-20', 'Risk', 'A pre-mortem exercise asks the team to...', '["Celebrate a launch","Imagine the project failed and explain why","Review last quarter","Estimate costs"]'::jsonb, 1, 'Imagining failure in advance surfaces risks people would otherwise not voice.', 41),
  ('2026-10-21', 'Finance', 'Contribution margin is...', '["Revenue minus variable costs","Revenue minus fixed costs","Net profit","Gross revenue"]'::jsonb, 0, 'It tells you how much each sale contributes toward covering fixed costs.', 42),
  ('2026-10-22', 'Customers', 'An ideal customer profile (ICP) describes...', '["Every possible buyer","The type of customer who gets the most value and is easiest to win and keep","Your largest customer","Investors"]'::jsonb, 1, 'Narrow beats broad early; it focuses product, marketing, and sales.', 43),
  ('2026-10-23', 'Pricing', 'Charging annually up front mainly improves...', '["Gross margin","Cash flow and retention","Product quality","Support load"]'::jsonb, 1, 'Cash now funds growth; annual commitments also reduce monthly churn decisions.', 44),
  ('2026-10-24', 'Negotiation', 'Reciprocity in negotiation means...', '["Refusing all concessions","A concession from you invites a concession from them","Splitting evenly","Threatening to leave"]'::jsonb, 1, 'Make concessions visible and conditional to trigger it.', 45),
  ('2026-10-25', 'Fundraising', 'A down round is...', '["A round led by angels","A financing at a lower valuation than the previous round","A bridge loan","A secondary sale"]'::jsonb, 1, 'Painful but survivable; anti-dilution terms decide who bears the cost.', 46),
  ('2026-10-26', 'Growth', 'Product-led growth relies on...', '["Large sales teams","The product itself driving acquisition, conversion, and expansion","TV advertising","Partnerships only"]'::jsonb, 1, 'Free trials, self-serve onboarding, and in-product virality are the tools.', 47),
  ('2026-10-27', 'Finance', 'A 30% discount on a product with 40% gross margin leaves a margin of...', '["10%","14%","28%","40%"]'::jsonb, 1, 'Price becomes 70; cost was 60; margin is 10/70 ≈ 14%. Discounts hit margin harder than they look.', 48),
  ('2026-10-28', 'Team', 'Psychological safety means team members...', '["Never disagree","Feel safe to raise problems and admit mistakes","Work remotely","Have job security"]'::jsonb, 1, 'Google''s team research found it the strongest predictor of team effectiveness.', 49),
  ('2026-10-29', 'Product', 'The Kano model separates features into...', '["Cheap and expensive","Basic expectations, performance features, and delighters","Front-end and back-end","Bugs and features"]'::jsonb, 1, 'Basics are expected, performance features scale satisfaction, delighters surprise.', 50),
  ('2026-10-30', 'Risk', 'Hedging is...', '["Betting bigger","Taking a position that offsets a risk you already hold","Avoiding all risk","Insurance fraud"]'::jsonb, 1, 'It reduces variance, usually at some cost to expected return.', 51),
  ('2026-10-31', 'Finance', 'Revenue recognition for a 12-month subscription paid up front happens...', '["All at once","Monthly over the 12 months","At renewal","When cash clears"]'::jsonb, 1, 'Cash is collected now; revenue is earned as the service is delivered.', 52),
